  for(const door of view.model.userData.doors){let part=door.parent;while(part&&!part.userData.partId)part=part.parent;const id=part?.userData.partId;if(!id)continue;counts[id]=(counts[id]||0)+1;this.rows.push({door,id,label:(door.userData.cover177?'Banco de baterías':({mt:'Celda MT',dc:'Distribución CD',control:'Control / RTU',rectifier:'Rectificador',transformer:'Resguardo transformador',aux:'Servicios auxiliares',battery:'Cargador auxiliar'})[id])+' '+counts[id],open:false,amount:0,closed:new THREE.Quaternion(),opened:door.quaternion.clone().normalize()});door.quaternion.identity();const row=this.rows.at(-1);door.updateWorldMatrix(true,true);const b=new THREE.Box3().setFromObject(door).applyMatrix4(door.matrixWorld.clone().invert()),side=Math.abs(b.min.x)>Math.abs(b.max.x)?-1:1;let handle=door.getObjectByName('Asidero');if(!handle&&door.userData.handle200){handle=new THREE.Object3D();handle.name='Contacto del tirador original200';handle.position.fromArray(door.userData.handle200);door.add(handle);}if(!handle){handle=new THREE.Mesh(new THREE.CapsuleGeometry(.012,.14,5,16),new THREE.MeshStandardMaterial({name:'Acero satinado tirador manual200',color:'#a5b1b4',metalness:.8,roughness:.34}));handle.name='Tirador manual200';handle.position.set(side<0?b.min.x+.08:b.max.x-.08,b.min.y+(b.max.y-b.min.y)*.48,new THREE.Vector3(0,0,-1).transformDirection(door.matrixWorld.clone().invert()).z<0?b.min.z-.035:b.max.z+.035);door.add(handle);}row.handle200=handle;}
